(''' * A membership ends exactly once: the write only matches a live row, so a
 * repeated removal is a conflict rather than a second, later `archivedAt`.
 */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(members.orgId, orgId),
          eq(members.id, memberId),
          liveMemberPredicate(),
        ),
      ),
