    .get();
''',''' * A membership ends exactly once: the write only matches a live row, so a
 * repeated removal is a conflict rather than a second, later `archivedAt`.
 *
 * Ending it also releases what the person held in the org, in the same
 * transaction: every issue assigned to them becomes unassigned and every
 * project they led is left without a lead (archived rows included — they can
 * be restored). Nothing in the org may point at a former member as the one
 * responsible for it, so the two cannot be allowed to drift apart.
 */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const row = getDb().transaction((tx) => {
    const patch = archivePatch();

    const ended = tx
      .update(members)
      .set(patch)
      .where(
        and(
          ...compact(
            orgPredicate(members.orgId, orgId),
            eq(members.id, memberId),
            liveMemberPredicate(),
          ),
        ),
      )
      .returning()
      .get();

    if (!ended) return undefined;

    tx.update(issues)
      .set({ assigneeId: null, updatedAt: patch.updatedAt })
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.assigneeId, ended.userId),
        ),
      )
      .run();

    tx.update(projects)
      .set({ leadId: null, updatedAt: patch.updatedAt })
      .where(
        and(
          orgPredicate(projects.orgId, orgId),
          eq(projects.leadId, ended.userId),
        ),
      )
      .run();

    return ended;
  });
'''),
])

