import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("~tests/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("~tests/server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("~tests/server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { toAppError } from "@/lib/errors";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as commentService from "@/server/services/comment-service";
import * as digestService from "@/server/services/digest-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import * as projectService from "@/server/services/project-service";
import * as sessionService from "@/server/services/session-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { listNotifications, notify } from "@/server/services/notification-service";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { createTenant, issueInput, useTemporaryDatabase } from "~tests/server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});
afterAll(() => cleanup());

const principal = (userId: any) => ({ userId, email: "x@y.z", activeOrgId: null, expiresAt: "2999-01-01T00:00:00.000Z" as any });

async function notifs(t: any, userId: any) {
  return (await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: userId, unreadOnly: false, limit: 50, cursor: null })).items;
}

describe("former members", () => {
  it("full lifecycle", async () => {
    const t = await createTenant("former-a", "growth");
    const other = await createTenant("former-b", "growth");
    await usageRepo.recomputeUsage(t.org.id);
    const user = t.userIds.member;
    // same user also member of other org
    await memberRepo.insertMember(other.org.id, user, "admin", null);
    const before = (await memberRepo.findMember(t.org.id, user))!;
    await sessionService.resolveActorForOrg(principal(user), t.org.slug);
    const seen = (await memberRepo.findMember(t.org.id, user))!;
    expect(seen.lastSeenAt).not.toBeNull();

    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: user, kind: "comment_created", inApp: true, email: true, digestOnly: true });
    expect(await digestService.listDigestRecipients(t.org.id)).toEqual([user]);

    const authored = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Authored by member" }));
    const assigned = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title: "Assigned to member", assigneeId: user, dueAt: "2020-01-01T00:00:00.000Z" }));
    await projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, leadId: user });
    expect((await notifs(t, user)).length).toBe(1); // issue.created doesn't notify; hmm

    const seatsBefore = (await usageRepo.getUsage(t.org.id)).seatsUsed;
    expect(seatsBefore).toBe(4);

    // ---- remove
    await memberService.removeMember(t.actors.admin, { orgId: t.org.id, memberId: before.id });
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(3);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(3);

    // cannot act / switch
    expect(await sessionService.resolveActorForOrg(principal(user), t.org.slug)).toBeNull();
    expect(await memberService.resolveActor(user, t.org.id)).toBeNull();
    await expect(sessionService.switchActiveOrg(principal(user), { orgId: t.org.id })).rejects.toThrow(/not a member/);
    // other workspace untouched
    expect(await sessionService.resolveActorForOrg(principal(user), other.org.slug)).toMatchObject({ role: "admin" });
    await expect(sessionService.switchActiveOrg(principal(user), { orgId: other.org.id })).resolves.toBeUndefined();
    expect((await orgRepo.listOrgsForUser(user)).map((o) => o.id)).toEqual([other.org.id]);

    // cascade
    expect((await issueRepo.findIssueById(t.org.id, assigned.id))!.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))!.leadId).toBeNull();

    // conflict on role change / second removal
    const e1 = await memberService.updateMemberRole(t.actors.admin, { orgId: t.org.id, memberId: before.id, role: "viewer" }).catch((e) => e);
    expect(e1).toBeInstanceOf(AlreadyArchivedError);
    expect(toAppError(e1).code).toBe("conflict");
    const e2 = await memberService.removeMember(t.actors.admin, { orgId: t.org.id, memberId: before.id }).catch((e) => e);
    expect(e2).toBeInstanceOf(AlreadyArchivedError);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(3);
    expect((await memberRepo.findMemberById(t.org.id, before.id))!.role).toBe("member");

    // assignment / lead refused as a whole
    const issueCount = await issueRepo.countIssues(t.org.id, t.project.id);
    await expect(issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { assigneeId: user }))).rejects.toThrow(/not a current member/);
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(issueCount);
    await expect(issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: assigned.id, assigneeId: user })).rejects.toThrow(/not a current member/);
    await expect(issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: assigned.id, assigneeId: other.userIds.viewer })).rejects.toThrow(/not a current member/);
    const projCount = await projectRepo.countProjects(t.org.id);
    await expect(projectService.createProject(t.actors.owner, { orgId: t.org.id, name: "Led by ghost", slug: "ghost", key: "GHO", description: null, visibility: "org", leadId: user, color: "#6366f1", targetDate: null })).rejects.toThrow(/not a current member/);
    expect(await projectRepo.countProjects(t.org.id)).toBe(projCount);
    await expect(projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, name: "Renamed", leadId: user })).rejects.toThrow(/not a current member/);
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))!.name).not.toBe("Renamed");

    // notifications
    const nBefore = (await notifs(t, user)).length;
    await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: authored.id, body: "hello @member", parentId: null, mentionedUserIds: [user] } as any);
    await runOverdueIssueJob(new Date());
    await notify(t.org.id, "issue_assigned", [user], { title: "x", body: "x", href: "/x", actorId: null });
    expect((await notifs(t, user)).length).toBe(nBefore);
    expect(await digestService.listDigestRecipients(t.org.id)).toEqual([]);
    expect(await digestService.buildDigest(t.org.id, user, "2000-01-01T00:00:00.000Z" as any, "2999-01-01T00:00:00.000Z" as any)).toBeNull();
    expect((await memberRepo.listMembers({ orgId: t.org.id, limit: 50, cursor: null })).items.map((m) => m.userId)).not.toContain(user);

    // ---- re-invite
    const token = "r".repeat(32);
    const inv = await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "member@former-a.test", role: "viewer", expiresInDays: 14 }, t.userIds.admin, hashToken(token));
    const joined: any[] = [];
    const off = subscribe("member.joined", (p) => { joined.push(p); });
    const back = await invitationService.acceptInvitation(user, { token });
    expect(back.id).toBe(before.id);
    expect(back).toMatchObject({ status: "active", archivedAt: null, role: "viewer", invitedBy: t.userIds.admin, createdAt: before.createdAt, lastSeenAt: seen.lastSeenAt });
    const used = (await invitationRepo.findInvitationByTokenHash(hashToken(token)))!;
