/**
 * Membership rows. Every read is filtered by `orgId`; removal is a soft delete.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import {
  and,
  count,
  desc,
  eq,
  inArray,
  isNotNull,
  isNull,
  like,
  or,
} from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  AlreadyArchivedError,
  archivePatch,
  isLive,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { getDb, issues, members, projects, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toMember, toUser } from "./_mappers";
import type { ListMembersInput } from "@/schemas/member";
import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Member, MemberWithUser, Role } from "@/types/member";

/**
 * A removed member is archived, never deleted, and no listing or count ever
 * surfaces one: the scope is fixed here rather than threaded through every
 * call site. The two raw lookups (`findMember`, `findMemberById`) are the
 * deliberate exception — see `isCurrentMember()`.
 */
const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};

function liveMemberPredicate() {
  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
}

/**
 * The one definition of "is a member right now": the membership is active and
 * has not ended. Removal leaves `status` untouched, so `status` alone never
 * answers this — every caller that needs the answer asks here.
 */
export function isCurrentMember(
  member: Pick<Member, "status" | "archivedAt">,
): boolean {
  return member.status === "active" && isLive(member);
}

/** SQL twin of `isCurrentMember()`. */
function currentMemberPredicates() {
  return compact(eq(members.status, "active"), liveMemberPredicate());
}
 *
 *  - nobody: a membership is created;
 *  - a former member: their existing membership is re-admitted — same row,
 *    now active, with the invitation's role and inviter and the acceptance
 *    time as the join date — rather than a second row for the same person;
 *  - a current member: nothing about them changes and no seat moves; the
 *    invitation is simply used up.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const acceptedAt = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMember(invitation.orgId, userId);

